    C c;
    OracleStub s0;
    OracleStub s1;

    function setUp() public {
        c = new C();
        s0 = new OracleStub();
        s1 = new OracleStub();
    }

    function testFuzz_property(
        uint8 payoffTypeRaw,
        uint8 directionRaw,
        uint256 dataSeed,
        uint256 oracleChoice,
        uint256 maintenanceSeed,
        uint256 feeSeed,
        string calldata name_,
        string calldata symbol_
    ) public {
        IProduct.ProductInfo memory info;
        info.name = name_;
        info.symbol = symbol_;
        // fuzzed choice of oracle actor (must have code, so choose among deployed stubs)
