            payoffDirection: PayoffDefinitionLib.PayoffDirection(directionRaw % 3),
            data: bytes30(bytes32(dataSeed))
        });
        info.maintenance = UFixed18.wrap(bound(maintenanceSeed, 0, 1e30));
        uint256 fee = bound(feeSeed, 0, 1e18); // fees must be <= ONE (1e18) to be admissible
