// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, IProduct, IOracleProvider, UFixed18, Fixed18, UFixed18Lib, PayoffDefinition, PayoffDefinitionLib, JumpRateUtilizationCurve, PackedFixed18, PackedUFixed18} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed, uint64 feeRaw) public {
        // keep fuzzed values in admissible domain (wide)
        uint256 m = uint256(bound(seed, 1, type(uint128).max));
        uint256 fee = bound(uint256(feeRaw), 0, 1e18); // fee <= ONE

        OracleStub oracleStub = new OracleStub();

        IProduct.ProductInfo memory info;
        info.name = "fuzz";
        info.symbol = "FZ";
        info.payoffDefinition = PayoffDefinition(
            PayoffDefinitionLib.PayoffType(1),
            PayoffDefinitionLib.PayoffDirection(0),
            bytes30(0)
        );
        info.oracle = oracleStub;
        info.maintenance = UFixed18.wrap(m);
        info.fundingFee = UFixed18.wrap(fee);
        info.makerFee = UFixed18.wrap(fee);
        info.takerFee = UFixed18.wrap(fee);
        info.positionFee = UFixed18.wrap(fee);
        info.makerLimit = UFixed18.wrap(m);
        info.utilizationCurve = JumpRateUtilizationCurve(
            PackedFixed18.wrap(int128(int256(m))),
            PackedFixed18.wrap(int128(int256(m))),
            PackedFixed18.wrap(int128(int256(m))),
            PackedUFixed18.wrap(uint128(m))
        );

        c.initialize(info);

        // General rule: after successful initialization, c's public oracle getter
        // must return the configured oracle contract (non-zero, with code),
        // for every admissible input. The mutant returns the zero address.
        assertTrue(address(c.oracle()) == address(oracleStub) && address(c.oracle()).code.length > 0);
    }
}

contract OracleStub {
    function implementation() external view returns (address) {
        return address(this);
    }
    function sync() external view returns (IOracleProvider.OracleVersion memory) {}
    function currentVersion() external view returns (IOracleProvider.OracleVersion memory) {}
    function atVersion(uint256) external view returns (IOracleProvider.OracleVersion memory) {}
}

