pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, IOracleProvider, IProduct, Fixed18, PayoffDefinitionLib} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 version, uint256 ts, uint256 rawPrice, uint256 maintenance) public {
        version = bound(version, 1, 10_000);
        ts = bound(ts, 0, 1e12);
        int256 price = int256(bound(rawPrice, 0, 2e18)) - 1e18;
        maintenance = bound(maintenance, 0, 1e18);

        OracleStub oracleStub = new OracleStub(version, ts, price);

        PayoffDefinition memory pd = PayoffDefinition(
            PayoffDefinitionLib.PayoffType(0),
            PayoffDefinitionLib.PayoffDirection(0),
            bytes30(0)
        );

        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "T",
            symbol: "T",
            payoffDefinition: pd,
            oracle: IOracleProvider(address(oracleStub)),
            maintenance: UFixed18Lib_u.wrap(maintenance),
            fundingFee: UFixed18Lib_u.wrap(0),
            makerFee: UFixed18Lib_u.wrap(0),
            takerFee: UFixed18Lib_u.wrap(0),
            positionFee: UFixed18Lib_u.wrap(0),
            makerLimit: UFixed18Lib_u.wrap(1e18),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18Lib_u.wrap(0),
                maxRate: PackedFixed18Lib_u.wrap(0),
                targetRate: PackedFixed18Lib_u.wrap(0),
                targetUtilization: PackedUFixed18Lib_u.wrap(0)
            })
        });

        c.initialize(info);

        bool ok;
        try c.currentVersion() returns (IOracleProvider.OracleVersion memory ov) {
            ok = (ov.version == version);
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract OracleStub is IOracleProvider {
    uint256 public v;
    uint256 public t;
    int256 public p;
    constructor(uint256 v_, uint256 t_, int256 p_) { v = v_; t = t_; p = p_; }
    function sync() external view returns (OracleVersion memory) { return currentVersion(); }
    function currentVersion() external view returns (OracleVersion memory) {
        return OracleVersion({version: v, timestamp: t, price: Fixed18.wrap(p)});
    }
    function atVersion(uint256) external view returns (OracleVersion memory) { return currentVersion(); }
}

