pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 feeSeed, uint256 oracleVersion) public {
        // Wide admissible domain: fees must be <= 1e18 (ONE); oracle version is arbitrary.
        uint256 fee = bound(feeSeed, 0, 1e18);
        uint256 v = oracleVersion;

        // Deploy a live oracle contract as the configured oracle (adversarial counterparty is not
        // needed as a failing party here; we need a *working* callee so P succeeds).
        OracleHelper oracle = new OracleHelper();

        // Build ProductInfo calldata without needing its Solidity type:
        // {string name, string symbol, PayoffDefinition{type, direction, bytes30},
        //  IOracleProvider oracle, 6 UFixed18 params, JumpRateUtilizationCurve{5 fields}}
        bytes memory productInfo = abi.encode(
            "N",
            "S",
            uint256(0),
            uint256(0),
            bytes30(0),
            address(oracle),
            uint256(1e18), // maintenance
            fee,           // fundingFee
            fee,           // makerFee
            fee,           // takerFee
            fee,           // positionFee
            uint256(1e18), // makerLimit
            int256(0), int256(0), int256(0), uint256(0), int256(0) // utilization curve
        );

        (bool initOk, ) = address(c).call(
            abi.encodeWithSelector(c.initialize.selector, productInfo)
        );
        assertTrue(initOk, "initialize must succeed");

        // Drive the oracle-backed public surface: atVersion delegates to the stored oracle.
        (bool ok, bytes memory ret) = address(c).staticcall(
            abi.encodeWithSignature("atVersion(uint256)", v)
        );

        // Reference: the oracle is a real contract, so the call completes with a full
        // OracleVersion (3 words). Mutant: oracle() returns address(0), staticcall yields
        // empty returndata and decoding reverts (or data is missing).
        assertTrue(ok && ret.length == 3 * 32, "oracle-backed view must return a full OracleVersion");
    }
}

contract OracleHelper {
    function sync() external pure returns (uint256, uint256, int256) {
        return (7, 1, 1e18);
    }

    function currentVersion() external pure returns (uint256, uint256, int256) {
        return (7, 1, 1e18);
    }

    function atVersion(uint256) external pure returns (uint256, uint256, int256) {
        return (7, 1, 1e18);
    }
}

