pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Initializer caller;

    function setUp() public {
        c = new C();
        caller = new Initializer();
    }

    function testFuzz_property(uint256 version, int256 price) public {
        OracleStub oracle = new OracleStub(version, price);

        // Try several candidate valid PayoffDefinition encodings; initialize must succeed for at least one.
        bool initialized = false;
        uint8[6] memory ptypes = [uint8(1), 1, 2, 2, 3, 1];
        uint8[6] memory pdirs = [uint8(1), 2, 1, 2, 1, 1];

        for (uint256 i = 0; i < 6 && !initialized; i++) {
            bytes memory payload = abi.encodePacked(
                c.initialize.selector,
                abi.encode(
                    "N",                       // name
                    "S",                       // symbol
                    uint8(ptypes[i]),           // payoffDefinition.payoffType
                    uint8(pdirs[i]),            // payoffDefinition.payoffDirection
                    bytes30(0),                 // payoffDefinition.data
                    address(oracle),            // oracle (a contract -> passes isContract check)
                    uint256(0),                 // maintenance
                    uint256(0),                 // fundingFee (<= 1e18)
                    uint256(0),                 // makerFee
                    uint256(0),                 // takerFee
                    uint256(0),                 // positionFee
                    uint256(0),                 // makerLimit
                    int256(0),                  // utilizationCurve.minRate (PackedFixed18)
                    int256(0),                  // utilizationCurve.maxRate
                    int256(0),                  // utilizationCurve.targetRate
                    uint256(0)                  // utilizationCurve.targetUtilization (PackedUFixed18)
                )
            );
            if (caller.doCall(address(c), payload)) initialized = true;
        }

        if (!initialized) return;

        // RULE: a successfully initialized product exposes the configured (non-zero, live) oracle.
        assertTrue(
            address(c.oracle()) == address(oracle) && address(c.oracle()).code.length > 0,
            "oracle() must return the configured non-zero oracle contract"
        );
    }
}

// Contract caller: initialize requires msg.sender (the controller) to have code.
contract Initializer {
    function doCall(address target, bytes memory payload) external returns (bool ok) {
        (ok, ) = target.call(payload);
    }
}

// Minimal live oracle so the isContract check passes and oracle() has an observable target.
contract OracleStub {
    uint256 public version;
    int256 public price;

    constructor(uint256 version_, int256 price_) {
        version = version_;
        price = price_;
    }

    function currentVersion() external view returns (uint256, uint256, int256) {
        return (version, block.timestamp, price);
    }

    function sync() external returns (uint256, uint256, int256) {
        return (version, block.timestamp, price);
    }

    function atVersion(uint256) external view returns (uint256, uint256, int256) {
        return (version, block.timestamp, price);
    }
}

