pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));

        // The stored oracle address is caller-independent: querying from
        // any account must return the same value as querying from this test contract.
        vm.prank(actor);
        address fromActor = address(c.oracle());
        address fromTest = address(c.oracle());

        assertTrue(fromActor == fromTest, "oracle() must not depend on caller");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Initializer init;

    // ABI-identical local mirrors of the src structs (enums/values map to uint8/uint256 etc.)
    struct PDTest { uint8 payoffType; uint8 payoffDirection; bytes30 data; }
    struct CurveTest { int128 minRate; int128 maxRate; int128 targetRate; uint128 targetUtilization; }
    struct InfoTest {
        string name;
        string symbol;
        PDTest payoffDefinition;
        address oracle;
        uint256 maintenance;
        uint256 fundingFee;
        uint256 makerFee;
        uint256 takerFee;
        uint256 positionFee;
        uint256 makerLimit;
        CurveTest utilizationCurve;
    }

    function setUp() public {
        c = new C();
        init = new Initializer();
    }

    function testFuzz_property(uint8 t, uint8 d, bytes30 data) public {
        // keep the definition in an admissible, nonzero domain
        vm.assume(t > 0 && t < 4);
        vm.assume(d < 2);
        vm.assume(data != bytes30(0));

        InfoTest memory info;
        info.name = "T";
        info.symbol = "T";
        info.payoffDefinition = PDTest(t, d, data);
        info.oracle = address(init); // must be a contract address
        info.maintenance = 1e18;
        info.fundingFee = 0;
        info.makerFee = 0;
        info.takerFee = 0;
        info.positionFee = 0;
        info.makerLimit = type(uint256).max;
        info.utilizationCurve = CurveTest(0, 0, 0, 0);

        // initialize must be invoked from a contract (controller check requires code at msg.sender)
        bytes memory payload = abi.encodeWithSelector(C.initialize.selector, info);
        init.go(address(c), payload);

        // read the public view payoffDefinition() and decode it
        (bool ok, bytes memory ret) = address(c).staticcall(abi.encodeWithSignature("payoffDefinition()"));
        assertTrue(ok, "payoffDefinition() reverted");
        (uint8 rt, uint8 rd, bytes30 rdata) = abi.decode(ret, (uint8, uint8, bytes30));

        // GENERAL RULE: payoffDefinition() always returns exactly the stored definition
        assertTrue(rt == t && rd == d && rdata == data);
    }
}

contract Initializer {
    function go(address target, bytes memory data) external {
        (bool ok, ) = target.call(data);
        require(ok, "init failed");
    }
}
